import{_ as t,o as s,c as a,a2 as i}from"./chunks/framework.il0noOp3.js";const u=JSON.parse('{"title":"Testing","description":"How to run and write Pester tests for AzureScout.","frontmatter":{"description":"How to run and write Pester tests for AzureScout."},"headers":[],"relativePath":"testing.md","filePath":"testing.md"}'),o={name:"testing.md"};function r(n,e,l,d,c,h){return s(),a("div",null,[...e[0]||(e[0]=[i(`<h1 id="testing" tabindex="-1">Testing <a class="header-anchor" href="#testing" aria-label="Permalink to &quot;Testing&quot;">​</a></h1><p>The test suite uses <a href="https://pester.dev" target="_blank" rel="noreferrer">Pester 5</a> and runs entirely offline — no Azure credentials or live API calls required. As of 2026-07-31 it is <strong>80 test files, 2,243 tests</strong>: 2,236 passing, 3 skipped, and 4 known cross-file flakes — a VM-quota context restore, an Excel retired-registration check, and two <code>Test-AZSCPermissions</code> scoping tests — that fail only when the whole suite shares one temp directory, and pass in isolation.</p><h2 id="prerequisites" tabindex="-1">Prerequisites <a class="header-anchor" href="#prerequisites" aria-label="Permalink to &quot;Prerequisites&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Requirement</th><th>Install Command</th></tr></thead><tbody><tr><td>PowerShell 7+</td><td>Built-in on modern Windows; <code>brew install --cask powershell</code> on macOS</td></tr><tr><td>Pester 5.3.2+</td><td><code>Install-Module Pester -MinimumVersion 5.3.2 -Force</code></td></tr><tr><td>ImportExcel</td><td><code>Install-Module ImportExcel -Force</code></td></tr></tbody></table><h2 id="running-the-full-suite" tabindex="-1">Running the Full Suite <a class="header-anchor" href="#running-the-full-suite" aria-label="Permalink to &quot;Running the Full Suite&quot;">​</a></h2><div class="language-powershell vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">powershell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">Import-Module</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> Pester </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">RequiredVersion </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">5.3</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">2</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> -</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Force</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">Invoke-Pester</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> -</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Path .\\tests\\ </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Output Detailed</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><p>This runs all 80 test files (2,243 tests: 2,236 passed, 3 skipped, 4 known cross-file flakes).</p><h2 id="running-a-single-test-file" tabindex="-1">Running a Single Test File <a class="header-anchor" href="#running-a-single-test-file" aria-label="Permalink to &quot;Running a Single Test File&quot;">​</a></h2><div class="language-powershell vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">powershell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Run only the declarative collector golden tests (all 240 collectors)</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">Invoke-Pester</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> -</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Path .\\tests\\DeclarativeCollectorGolden.Tests.ps1 </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Output Detailed</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Run only the private main-function tests</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">Invoke-Pester</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> -</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Path .\\tests\\Private.Main.Tests.ps1 </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Output Detailed</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br></div></div><h2 id="test-file-overview" tabindex="-1">Test File Overview <a class="header-anchor" href="#test-file-overview" aria-label="Permalink to &quot;Test File Overview&quot;">​</a></h2><p>The <code>tests/</code> directory contains 80 Pester files. There is no longer one test file per collector category — the old <code>&lt;Category&gt;.Module.Tests.ps1</code> files (<code>Compute.Module.Tests.ps1</code>, <code>Databases.Module.Tests.ps1</code>, and so on) tested imperative <code>.ps1</code> collectors under <code>Modules/Public/InventoryModules/</code>, and were retired when every collector was rewritten as a declarative <code>.psd1</code> definition (Epic AB#5638, AB#5659). All 240 collectors are now tested by the files below instead.</p><h3 id="collector-tests" tabindex="-1">Collector Tests <a class="header-anchor" href="#collector-tests" aria-label="Permalink to &quot;Collector Tests&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Test File</th><th>What it proves</th></tr></thead><tbody><tr><td><code>DeclarativeCollectorGolden.Tests.ps1</code></td><td>For every <code>.psd1</code> under <code>manifests/collectors/**</code>, the interpreter reproduces a <strong>committed golden output</strong> — same rows, order, keys, values, null/array shape, and the same Excel worksheet columns/cells under both tag states. This is the primary correctness proof and does not read any collector <code>.ps1</code> (there are none left).</td></tr><tr><td><code>ResourceTypeExistence.Tests.ps1</code></td><td>Every resource type a collector declares exists in Azure — see <a href="#the-resource-type-existence-gate">the resource-type existence gate</a> below.</td></tr><tr><td><code>DeclarativeCollectorCutover.Tests.ps1</code></td><td>The declarative interpreter path is actually what runs in production — not a parallel path nobody calls.</td></tr><tr><td><code>CollectorDefinitionSchema.Tests.ps1</code></td><td>Every <code>.psd1</code> definition is structurally valid (required keys present, correct types) before the interpreter ever sees it.</td></tr><tr><td><code>ManifestCategory.Tests.ps1</code></td><td>Every collector&#39;s folder matches a <code>-Category</code> <code>[ValidateSet]</code> entry, and every <code>[ValidateSet]</code> entry has a folder.</td></tr><tr><td><code>ManifestCollectorRuntime.Tests.ps1</code></td><td>Collectors execute end-to-end through <code>Invoke-ScoutCollector</code> against mock resources.</td></tr><tr><td><code>Collector.SparsePayload.Tests.ps1</code></td><td>Collectors survive a payload missing properties they normally read, instead of dropping a whole worksheet — AB#6839/AB#6844.</td></tr><tr><td><code>Collect.ArmChildResources.Tests.ps1</code></td><td>Child-loop collectors (agent pools, backup items, etc.) render the parent resource even when children are absent — AB#6845.</td></tr><tr><td><code>ServiceCoverage.Tests.ps1</code></td><td>Category/collector counts documented in <code>docs/</code> (arm-modules.md, coverage-table.md) match the manifests on disk.</td></tr></tbody></table><h3 id="fixture-generation" tabindex="-1">Fixture Generation <a class="header-anchor" href="#fixture-generation" aria-label="Permalink to &quot;Fixture Generation&quot;">​</a></h3><p>Golden tests need fixtures that reach every field expression a collector reads, or the proof is vacuous — a fixture with an empty <code>properties</code> bag makes any broken expression and any working one both emit nulls and compare equal. <code>scripts/New-ScoutCollectorFixture.ps1</code> derives the fixture from the collector&#39;s <strong>own</strong> <code>.psd1</code> definition: it walks the AST of the lifted preamble and field expressions, finds every property path reached from the row variable, and synthesises a resource with exactly those paths populated. A hand-written fixture tends to under-populate; a derived one cannot, because every path the collector reads is present by construction. What it cannot do is invent realistic <em>values</em> — see the script&#39;s own <code>Honest limits</code> notes.</p><h3 id="private-module-tests-4-files" tabindex="-1">Private Module Tests (4 files) <a class="header-anchor" href="#private-module-tests-4-files" aria-label="Permalink to &quot;Private Module Tests (4 files)&quot;">​</a></h3><p>These validate internal helper scripts — file existence, syntax (via <code>Parser::ParseFile</code>), and function definitions.</p><table tabindex="0"><thead><tr><th>Test File</th><th>Scripts Covered</th></tr></thead><tbody><tr><td><code>Private.Main.Tests.ps1</code></td><td>13 (orchestration, auth, caching)</td></tr><tr><td><code>Private.Extraction.Tests.ps1</code></td><td>9 (API, Graph, subscriptions)</td></tr><tr><td><code>Private.Processing.Tests.ps1</code></td><td>9 (cache, advisory, policy jobs)</td></tr><tr><td><code>Private.Reporting.Tests.ps1</code></td><td>23 (Excel, JSON, Markdown, AsciiDoc) — now covers <code>src/report/renderers/inventory/</code>, not <code>Modules/Private/Reporting/</code>, which no longer exists (AB#5662). Also builds a real <code>.xlsx</code> from a real <code>ReportCache</code> and asserts no Excel COM was used (AB#5665).</td></tr></tbody></table><h3 id="public-function-integration-tests-10-files" tabindex="-1">Public Function &amp; Integration Tests (10 files) <a class="header-anchor" href="#public-function-integration-tests-10-files" aria-label="Permalink to &quot;Public Function &amp; Integration Tests (10 files)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Test File</th><th>Purpose</th></tr></thead><tbody><tr><td><code>Public.Functions.Tests.ps1</code></td><td>14 public utility scripts (Diagram, Jobs)</td></tr><tr><td><code>AzureScout.Tests.ps1</code></td><td>Module manifest &amp; import validation</td></tr><tr><td><code>Invoke-AzureScout.Tests.ps1</code></td><td>Main entry-point parameter handling</td></tr><tr><td><code>Connect-AZSCLoginSession.Tests.ps1</code></td><td>Authentication flows</td></tr><tr><td><code>Invoke-AZSCGraphRequest.Tests.ps1</code></td><td>Graph API request handling</td></tr><tr><td><code>Test-AZSCPermissions.Tests.ps1</code></td><td>Permission checker logic</td></tr><tr><td><code>Start-AZSCEntraExtraction.Tests.ps1</code></td><td>Entra ID extraction</td></tr><tr><td><code>PermissionAudit.Tests.ps1</code></td><td>Permission audit pipeline</td></tr><tr><td><code>OutputFormat.Tests.ps1</code></td><td>Output format routing</td></tr><tr><td><code>CategoryFiltering.Tests.ps1</code></td><td>Category filter validation</td></tr></tbody></table><h2 id="how-the-declarative-collector-golden-tests-work" tabindex="-1">How the declarative collector golden tests work <a class="header-anchor" href="#how-the-declarative-collector-golden-tests-work" aria-label="Permalink to &quot;How the declarative collector golden tests work&quot;">​</a></h2><p>Every <code>.psd1</code> under <code>manifests/collectors/**</code> is proved the same way, driven entirely by the definition file — there is no per-collector test code to write:</p><ol><li><strong>Discovery</strong> — <code>DeclarativeCollectorGolden.Tests.ps1</code> enumerates every category folder and every <code>.psd1</code> inside it; each becomes one Pester test case.</li><li><strong>Fixture</strong> — <code>scripts/New-ScoutCollectorFixture.ps1</code> derives a synthetic resource for that collector from its own field expressions (see <a href="#fixture-generation">Fixture Generation</a> above), or a shared fixture is used for collectors that share an input shape (e.g. <code>Databases</code>).</li><li><strong>Run</strong> — <code>src/pipeline/Invoke-ScoutDeclarativeCollector.ps1</code> runs the definition against the fixture for both the Processing and Reporting tasks, under both tag states.</li><li><strong>Compare</strong> — The result is compared field-for-field against a <strong>committed golden record</strong> in <code>tests/fixtures/collector-golden/&lt;Category&gt;/&lt;Name&gt;.json</code> — rows, order, keys, values, and null/array shape must match exactly, and the rendered Excel worksheet&#39;s columns and cells must match too.</li></ol><p>Golden records are updated only through a reviewed, documented behavior change — never regenerated to make a failing test pass.</p><h2 id="how-private-module-tests-work" tabindex="-1">How Private Module Tests Work <a class="header-anchor" href="#how-private-module-tests-work" aria-label="Permalink to &quot;How Private Module Tests Work&quot;">​</a></h2><p>Private module tests validate scripts that are not directly invoked by users:</p><ul><li><strong>File existence</strong> — Confirms every expected <code>.ps1</code> file is present.</li><li><strong>Syntax validation</strong> — Uses <code>[System.Management.Automation.Language.Parser]::ParseFile()</code> to catch parse errors without executing any code.</li><li><strong>Function definitions</strong> — Verifies each script defines the expected function name via regex search of the file content.</li><li><strong>Unit tests</strong> — For simple utilities (e.g., <code>Clear-AZSCMemory</code>, <code>Set-AZSCFolder</code>), the function is dot-sourced and invoked with mocked dependencies.</li></ul><h2 id="writing-tests-for-a-new-collector" tabindex="-1">Writing Tests for a New Collector <a class="header-anchor" href="#writing-tests-for-a-new-collector" aria-label="Permalink to &quot;Writing Tests for a New Collector&quot;">​</a></h2><p>When you add a new <code>.psd1</code> collector definition under <code>manifests/collectors/&lt;Category&gt;/</code>:</p><ol><li>Run <code>scripts/New-ScoutCollectorFixture.ps1</code> for the category (or add to the shared fixture) to generate a fixture that reaches every field expression the definition declares.</li><li>Run <code>DeclarativeCollectorGolden.Tests.ps1</code> once with no committed golden record — it will show you the produced output.</li><li>Review that output by hand, then commit it as the golden record under <code>tests/fixtures/collector-golden/&lt;Category&gt;/&lt;Name&gt;.json</code>.</li><li>Re-run the test file and verify it passes against the committed record.</li><li>Confirm every resource type you declared is real — <code>ResourceTypeExistence.Tests.ps1</code> checks this automatically, but see <a href="#the-resource-type-existence-gate">the gate section</a> below for how to add a provider newer than the committed catalogue.</li></ol><p>See <code>docs/design/decisions/declarative-collectors.md</code> for the full <code>.psd1</code> schema and <a href="./contributing.html">Contributing</a> for the rest of the PR workflow.</p><h2 id="the-resource-type-existence-gate" tabindex="-1">The resource-type existence gate <a class="header-anchor" href="#the-resource-type-existence-gate" aria-label="Permalink to &quot;The resource-type existence gate&quot;">​</a></h2><p><code>tests/ResourceTypeExistence.Tests.ps1</code> checks every resource type a collector manifest declares against a committed catalogue of <strong>real</strong> Azure provider/type pairs. It runs offline, on every pull request, as part of the normal suite.</p><p><strong>Why it cannot be replaced by an ordinary test.</strong> <code>scripts/New-ScoutCollectorFixture.ps1</code> derives each collector&#39;s fixture estate from that collector&#39;s <em>own</em> expressions, so the declared resource type is fabricated into existence and every property it reads is present by construction. A collector for a type Azure does not have therefore passes forever — the manifests are the thing under test, so they cannot also be the ground truth. <code>Hybrid/ArcSites</code> declared three non-existent type strings and shipped green through every release before this gate existed.</p><p>It is also the only coverage check that works on a <strong>small tenant</strong>: it needs the resource provider to be real, not for you to own one of the resources.</p><h3 id="refreshing-the-catalogue" tabindex="-1">Refreshing the catalogue <a class="header-anchor" href="#refreshing-the-catalogue" aria-label="Permalink to &quot;Refreshing the catalogue&quot;">​</a></h3><p><code>manifests/azure-provider-types.json</code> is read from ARM and committed. Refresh it when you add a collector for a provider newer than the file&#39;s <code>GeneratedAt</code>, or when the gate reports a type you have independently confirmed is real:</p><div class="language-powershell vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">powershell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">Connect-AzAccount</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">/</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">scripts</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">/</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">Update-ScoutProviderCatalog.ps1</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><p>It reads <code>Get-AzResourceProvider -ListAvailable</code>, which returns every provider ARM knows about regardless of whether your subscription has registered it — so any subscription in any tenant produces the same catalogue. Commit the result, and say in the commit message when it was taken.</p><h3 id="what-the-gate-deliberately-does-not-fail-on" tabindex="-1">What the gate deliberately does not fail on <a class="header-anchor" href="#what-the-gate-deliberately-does-not-fail-on" aria-label="Permalink to &quot;What the gate deliberately does not fail on&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Case</th><th>Treatment</th><th>Why</th></tr></thead><tbody><tr><td><code>AZSC/…</code>, <code>entra/…</code>, <code>devops/…</code></td><td>Skipped</td><td>Scout&#39;s own synthetic TYPE strings. They have no ARM counterpart by design, so no catalogue can contain them.</td></tr><tr><td>Three-segment child types (<code>…/vaults/backupPolicies</code>)</td><td>Checked against the <strong>parent</strong></td><td>ARM&#39;s provider metadata under-reports nested types — <code>Microsoft.RecoveryServices/vaults</code> is listed but most of its <code>vaults/backup*</code> children are not, and they are real and callable. A child of a <em>non-existent</em> parent is still rejected.</td></tr><tr><td>Whether a real type returns any rows</td><td>Not checked</td><td>That is a live-run question. Conflating &quot;the type does not exist&quot; with &quot;this tenant has none&quot; is exactly the ambiguity the row-count artifact exists to remove.</td></tr></tbody></table><h2 id="common-pitfalls" tabindex="-1">Common Pitfalls <a class="header-anchor" href="#common-pitfalls" aria-label="Permalink to &quot;Common Pitfalls&quot;">​</a></h2><ul><li><strong>Case-sensitive hashtable keys</strong> — PowerShell hashtable keys are case-insensitive; avoid duplicate keys like <code>SKU</code> and <code>sku</code> in mock data.</li><li><strong>ARM ID format</strong> — Some modules call <code>.split(&#39;/&#39;)[8]</code> on resource IDs. Always use full ARM paths (e.g., <code>/subscriptions/.../resourceGroups/.../providers/.../name</code>) in mocks.</li><li><strong>DateTime values</strong> — Modules that cast properties to <code>[datetime]</code> will fail if mock values aren&#39;t valid date strings.</li><li><strong>Cross-resource lookups</strong> — Some modules (e.g., Backup) join data across multiple resource types. Include mock resources for all related types.</li><li><strong>Export-Excel -PassThru</strong> — This pattern does not save the file to disk. Test the Reporting phase with <code>Should -Not -Throw</code> rather than checking for file existence.</li></ul><h2 id="testing-the-caf-waf-assessment-platform" tabindex="-1">Testing the CAF/WAF assessment platform <a class="header-anchor" href="#testing-the-caf-waf-assessment-platform" aria-label="Permalink to &quot;Testing the CAF/WAF assessment platform&quot;">​</a></h2><p>The tests above cover the <strong>inventory-mode</strong> modules and pipeline. The <strong>assessment layers</strong> (<code>src/collect</code>, <code>src/assess</code>, <code>src/report</code>) have their own, separate test coverage:</p><ul><li><strong><code>tests/Assessment.Engine.Tests.ps1</code></strong> — pure-logic smoke tests for the rule engine: JSONPath resolution (<code>Resolve-JsonPath</code>), rule assertion semantics (<code>Invoke-Rule</code>), and CAF/WAF scoring math (<code>Get-Score</code>). No Azure connection.</li><li><strong><code>tests/datadump/</code></strong> — synthetic fixture data used to offline-render each report tier without a live tenant: <code>Test-ExcelFromDataDump.ps1</code>, <code>Test-PowerBIFromDataDump.ps1</code>, and <code>Test-PptxFromDataDump.ps1</code> render the Excel evidence, Power BI CSV bundle, and PowerPoint deck respectively from the same fixture <code>findings.json</code>/<code>collect.json</code> shape.</li></ul><p>Run them the same way as the rest of the suite:</p><div class="language-powershell vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">powershell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">Invoke-Pester</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> -</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Path .\\tests\\Assessment.Engine.Tests.ps1 </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Output Detailed</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><h2 id="ci-cd-integration" tabindex="-1">CI / CD Integration <a class="header-anchor" href="#ci-cd-integration" aria-label="Permalink to &quot;CI / CD Integration&quot;">​</a></h2><p>To run the test suite in a CI pipeline (GitHub Actions, Azure DevOps, etc.):</p><div class="language-yaml vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># GitHub Actions example</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">- </span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">name</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">Run Pester Tests</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  shell</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">pwsh</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  run</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">|</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">    Install-Module Pester -RequiredVersion 5.3.2 -Force -Scope CurrentUser</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">    Install-Module ImportExcel -Force -Scope CurrentUser</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">    Import-Module Pester -RequiredVersion 5.3.2 -Force</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">    $result = Invoke-Pester -Path ./tests/ -Output Detailed -PassThru</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">    if ($result.FailedCount -gt 0) { exit 1 }</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br></div></div>`,51)])])}const g=t(o,[["render",r]]);export{u as __pageData,g as default};
